layer.css:
[data-ryt="pitch"] { color: var(--ryt-muted); border-left: 3px solid rgb(102, 51, 153); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 400; font-style: italic; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 15px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); border-top: 6px dotted rgb(102, 51, 153); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 3px solid rgb(220, 20, 60); border-radius: 0px; transition: background-color 0.2s, color 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-bottom: 3px solid rgb(220, 20, 60); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.2s, color 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-bottom: 3px solid rgb(220, 20, 60); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22.5px; font-weight: 700; font-style: normal; line-height: 1.667; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.2s, color 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="nav"] a { color: var(--ryt-text); border-bottom: 3px solid rgb(220, 20, 60); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 400; font-style: normal; line-height: 2.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: background-color 0.2s, color 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 13.5px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-bottom: 3px solid rgb(220, 20, 60); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.2s, color 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]::before { content: "# "; display: inline; color: rgb(220, 20, 60); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(220, 20, 60); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(220, 20, 60) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { background-color: #b91c3c; background-color: #50fa7b; color: rgb(0, 0, 0); outline-color: #50fa7b }
[data-ryt="nav"] a:hover { background-color: #b91c3c; background-color: #50fa7b; color: rgb(0, 0, 0); outline-color: #50fa7b }
[data-ryt="brand"]:hover { background-color: #b91c3c; background-color: #50fa7b; color: rgb(0, 0, 0); outline-color: #50fa7b }
[data-ryt="hero"] h1::before { content: "# "; display: inline; color: rgb(220, 20, 60); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(220, 20, 60); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(220, 20, 60) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { background-color: #b91c3c; background-color: #50fa7b; color: rgb(0, 0, 0); outline-color: #50fa7b }
article[data-ryt="rec-card"]:hover { background-color: #b91c3c; color: var(--ryt-bg); background-color: #50fa7b; color: rgb(0, 0, 0); outline-color: #50fa7b }
